package io.aetheris.orchestrator.voice;import org.springframework.stereotype.Service;import java.util.*;@Service public class SpeechAdapterCatalog {private final List<SpeechToTextAdapter> stt;private final List<TextToSpeechAdapter> tts;public SpeechAdapterCatalog(Optional<List<SpeechToTextAdapter>> stt,Optional<List<TextToSpeechAdapter>> tts){this.stt=stt.orElse(List.of());this.tts=tts.orElse(List.of());}public Map<String,Object> status(){return Map.of("stt",stt.stream().map(a->Map.of("id",a.id(),"available",a.available())).toList(),"tts",tts.stream().map(a->Map.of("id",a.id(),"available",a.available())).toList(),"hardwareIntegrated",false);}}
